<?php
require __DIR__.'/bootstrap.php';require_auth();if(!can('payments.view')){http_response_code(403);exit('Forbidden');}require __DIR__.'/partials.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'create';$db->beginTransaction();try{
 if($action==='create_customer'){$name=trim($_POST['customer_name']??'');if($name==='')throw new RuntimeException('Enter the customer name.');$next=(int)$db->query('SELECT COALESCE(MAX(id),0)+1 FROM customers')->fetchColumn();$code=trim($_POST['customer_code']??'')?:'CUS-'.str_pad((string)$next,5,'0',STR_PAD_LEFT);$type=in_array($_POST['customer_type']??'',['retail','wholesale','both'],true)?$_POST['customer_type']:'retail';$period=in_array($_POST['default_payment_period']??'',['7_days','14_days','30_days','end_of_month'],true)?$_POST['default_payment_period']:'30_days';$db->prepare('INSERT INTO customers(customer_code,name,phone,business_name,address,customer_type,credit_enabled,default_payment_period) VALUES(?,?,?,?,?,?,1,?)')->execute([$code,$name,trim($_POST['phone']??''),trim($_POST['business_name']??''),trim($_POST['address']??''),$type,$period]);$customerId=(int)$db->lastInsertId();audit($db,'create','customer',$customerId,null,['name'=>$name,'created_from'=>'customer_advance','credit_enabled'=>1]);$db->commit();flash('success','Customer account created. You can now record the advance.');redirect('advances.php?customer_id='.$customerId);}
 if($action==='create'){$customerId=(int)($_POST['customer_id']??0);$amount=(float)($_POST['amount']??0);if(!$customerId||$amount<=0)throw new RuntimeException('Choose a customer and enter the advance amount.');$customer=$db->prepare('SELECT id FROM customers WHERE id=? AND status="active"');$customer->execute([$customerId]);if(!$customer->fetchColumn())throw new RuntimeException('Customer not found.');$next=(int)$db->query('SELECT COALESCE(MAX(id),0)+1 FROM customer_advances')->fetchColumn();$no='ADV-'.date('Y').'-'.str_pad((string)$next,6,'0',STR_PAD_LEFT);$productId=(int)($_POST['product_id']??0)?:null;$qty=$productId?max(0,(float)($_POST['reserved_quantity']??0)):null;$expected=$productId?max(0,(float)($_POST['expected_unit_price']??0)):null;$db->prepare('INSERT INTO customer_advances(advance_no,customer_id,product_id,reserved_quantity,expected_unit_price,amount,remaining_amount,received_at,method,reference_no,notes,created_by) VALUES(?,?,?,?,?,?,?,NOW(),?,?,?,?)')->execute([$no,$customerId,$productId,$qty,$expected,$amount,$amount,$_POST['method'],trim($_POST['reference_no']??''),trim($_POST['notes']??''),user()['id']]);$id=(int)$db->lastInsertId();audit($db,'create','customer_advance',$id,null,['advance_no'=>$no,'amount'=>$amount,'customer_id'=>$customerId,'product_id'=>$productId]);$db->commit();flash('success',"Advance $no saved. It is not sales revenue until applied to an invoice.");redirect('advance_receipt.php?id='.$id);}
 if($action==='apply'){$advanceId=(int)$_POST['advance_id'];$saleId=(int)$_POST['sale_id'];$amount=(float)$_POST['apply_amount'];$a=$db->prepare('SELECT * FROM customer_advances WHERE id=? FOR UPDATE');$a->execute([$advanceId]);$advance=$a->fetch();if(!$advance||!in_array($advance['status'],['open','partially_applied'],true))throw new RuntimeException('This advance is not available.');$s=$db->prepare('SELECT * FROM sales WHERE id=? AND customer_id=? AND payment_type="credit" AND status NOT IN("cancelled","returned") FOR UPDATE');$s->execute([$saleId,$advance['customer_id']]);$sale=$s->fetch();if(!$sale||(float)$sale['balance']<=0)throw new RuntimeException('Choose an unpaid credit invoice for this customer.');$amount=min($amount,(float)$advance['remaining_amount'],(float)$sale['balance']);if($amount<=0)throw new RuntimeException('Enter an amount to apply.');$newAdvance=(float)$advance['remaining_amount']-$amount;$newBalance=(float)$sale['balance']-$amount;$db->prepare('INSERT INTO customer_advance_applications(advance_id,sale_id,amount,applied_at,applied_by) VALUES(?,?,?,NOW(),?)')->execute([$advanceId,$saleId,$amount,user()['id']]);$db->prepare('UPDATE customer_advances SET remaining_amount=?,status=? WHERE id=?')->execute([$newAdvance,$newAdvance<=0?'applied':'partially_applied',$advanceId]);$db->prepare('UPDATE sales SET paid_amount=paid_amount+?,balance=?,status=? WHERE id=?')->execute([$amount,$newBalance,$newBalance<=0?'paid':'partially_paid',$saleId]);$db->prepare('UPDATE customers SET outstanding=GREATEST(0,outstanding-?),total_payments=total_payments+?,last_payment_at=NOW() WHERE id=?')->execute([$amount,$amount,$advance['customer_id']]);audit($db,'apply','customer_advance',$advanceId,null,['sale_id'=>$saleId,'amount'=>$amount]);$db->commit();flash('success','Advance applied to '.$sale['sale_no'].'. Invoice and customer balance updated.');redirect('sale_view.php?id='.$saleId);}
 throw new RuntimeException('Invalid action.');
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();flash('danger',$e->getMessage());redirect('advances.php');}}
$customers=$db->query('SELECT id,customer_code,name,phone FROM customers WHERE status="active" ORDER BY name')->fetchAll();$products=$db->query('SELECT id,item_code,name,retail_price,wholesale_price,current_stock FROM products WHERE status="active" ORDER BY current_stock<=0,current_stock,name')->fetchAll();
$advances=$db->query('SELECT a.*,c.name customer,c.phone,p.item_code,p.name product,u.display_name received_by FROM customer_advances a JOIN customers c ON c.id=a.customer_id LEFT JOIN products p ON p.id=a.product_id JOIN users u ON u.id=a.created_by ORDER BY a.id DESC')->fetchAll();
$openSales=$db->query('SELECT s.id,s.customer_id,s.sale_no,s.balance FROM sales s WHERE s.payment_type="credit" AND s.balance>0 AND s.status NOT IN("cancelled","returned") ORDER BY s.sale_date,s.id')->fetchAll();
page_start('Customer Advances','advances.php');?>
<section class="info-strip"><span class="step-number">Rs</span><div><b>Advance money received before the final invoice</b><p>It remains customer money held by the business. Apply it only after creating that customer's credit invoice.</p></div></section>
<div class="advance-layout"><section class="panel table-panel"><div class="panel-head"><div><span class="eyebrow">Advance register</span><h3>Customer advances</h3></div></div><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Customer</th><th>Reserved Item</th><th class="right">Received</th><th class="right">Available</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(!$advances):?><tr><td colspan="7">No advances recorded.</td></tr><?php endif;?><?php foreach($advances as $a):?><tr><td><b><?=e($a['advance_no'])?></b><br><small><?=date('d M Y, H:i',strtotime($a['received_at']))?></small></td><td><?=e($a['customer'])?><br><small><?=e($a['phone']?:'')?></small></td><td><?=e($a['product']?($a['item_code'].' - '.$a['product'].' × '.$a['reserved_quantity']):'General advance')?></td><td class="right"><?=money($a['amount'])?></td><td class="right"><b><?=money($a['remaining_amount'])?></b></td><td><span class="status status-<?=e(str_replace('_','-',$a['status']))?>"><?=e(ucwords(str_replace('_',' ',$a['status'])))?></span></td><td><a href="advance_receipt.php?id=<?=$a['id']?>">View / Print</a><?php if((float)$a['remaining_amount']>0):?><br><button type="button" class="link-button" data-apply-advance="<?=$a['id']?>" data-customer="<?=$a['customer_id']?>" data-remaining="<?=$a['remaining_amount']?>">Apply to Invoice</button><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<aside class="panel"><div class="panel-head"><div><span class="eyebrow">New receipt</span><h3>Receive an Advance</h3></div></div><form method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="create"><label>Customer<select name="customer_id" required><option value="">Choose customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'].' · '.$c['phone'])?></option><?php endforeach;?></select></label><label>Reserved item (optional)<select name="product_id" id="advance-product"><option value="">General advance / item not decided</option><?php foreach($products as $p):?><option value="<?=$p['id']?>" data-price="<?=$p['retail_price']?>"><?=e($p['item_code'].' - '.$p['name'].' · Stock '.$p['current_stock'])?></option><?php endforeach;?></select></label><div class="form-grid"><label>Reserved quantity<input type="number" name="reserved_quantity" min="0" step=".001"></label><label>Expected unit price<input type="number" name="expected_unit_price" min="0" step=".01"></label></div><label>Advance amount<input type="number" name="amount" min=".01" step=".01" required></label><label>Received using<select name="method"><option value="cash">Cash</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option><option value="cheque">Cheque</option></select></label><label>Reference<input name="reference_no"></label><label>Notes<textarea name="notes" rows="3"></textarea></label><button class="btn primary wide">Save Advance & Print Receipt</button></form></aside></div>
<div class="advance-apply-modal" hidden><form method="post" class="panel"><button type="button" class="icon-button" data-close-advance>×</button><span class="eyebrow">Use advance</span><h3>Apply to a Credit Invoice</h3><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="apply"><input type="hidden" name="advance_id"><label>Customer's unpaid invoice<select name="sale_id" required><option value="">Choose invoice</option><?php foreach($openSales as $s):?><option value="<?=$s['id']?>" data-customer="<?=$s['customer_id']?>" data-balance="<?=$s['balance']?>"><?=e($s['sale_no'].' · Due '.money($s['balance']))?></option><?php endforeach;?></select></label><label>Amount to apply<input type="number" name="apply_amount" min=".01" step=".01" required></label><p class="plain-help">The invoice due and customer outstanding balance will both decrease.</p><button class="btn primary wide">Apply Advance</button></form></div>
<div class="advance-customer-modal" hidden><form method="post" class="panel"><button type="button" class="icon-button" data-close-advance-customer>×</button><span class="eyebrow">Quick customer account</span><h3>Create Customer</h3><p class="muted">The new customer will be selected automatically in the advance form.</p><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="create_customer"><div class="form-grid"><label class="full">Customer name<input name="customer_name" required></label><label>Phone<input name="phone"></label><label>Customer code (optional)<input name="customer_code"></label><label>Business / shop<input name="business_name"></label><label>Customer type<select name="customer_type"><option value="retail">Retail</option><option value="wholesale">Wholesale</option><option value="both">Retail and Wholesale</option></select></label><label>Default credit period<select name="default_payment_period"><option value="7_days">7 days</option><option value="14_days">14 days</option><option value="30_days" selected>30 days</option><option value="end_of_month">End of month</option></select></label><label class="full">Address<textarea name="address" rows="2"></textarea></label></div><div class="plain-help"><b>Credit account will be enabled.</b><br>The advance itself does not create customer debt.</div><button class="btn primary wide">Create Customer & Continue</button></form></div>
<style>.advance-layout{display:grid;grid-template-columns:1fr;gap:24px}.advance-layout aside label{display:block;margin-bottom:13px}.link-button{border:0;background:none;padding:4px 0;color:#145b41;font-weight:800;cursor:pointer}.advance-apply-modal,.advance-create-overlay,.advance-customer-modal{position:fixed;inset:0;background:#13271fcc;z-index:100;display:grid;place-items:center;padding:20px}.advance-apply-modal[hidden],.advance-create-overlay[hidden],.advance-customer-modal[hidden]{display:none}.advance-apply-modal form,.advance-customer-modal form{width:min(620px,100%);max-height:90vh;overflow:auto;position:relative}.advance-apply-modal .icon-button,.advance-customer-modal .icon-button{position:absolute;right:16px;top:16px}.advance-apply-modal label{display:block;margin:16px 0}.advance-create-overlay>aside{width:min(620px,100%);max-height:90vh;overflow:auto;position:relative}.advance-create-overlay .advance-create-close{position:absolute;right:16px;top:16px}.advance-register-actions{display:flex;align-items:center;gap:10px}.create-customer-from-advance{width:100%;margin:-3px 0 14px}</style>
<script>document.querySelector('#advance-product')?.addEventListener('change',e=>{const price=e.target.selectedOptions[0]?.dataset.price,target=document.querySelector('[name="expected_unit_price"]');if(price&&target&&!target.value)target.value=price});const modal=document.querySelector('.advance-apply-modal');document.addEventListener('click',e=>{const b=e.target.closest('[data-apply-advance]');if(!b)return;modal.hidden=false;modal.querySelector('[name="advance_id"]').value=b.dataset.applyAdvance;const select=modal.querySelector('[name="sale_id"]');[...select.options].forEach(o=>o.hidden=o.value&&o.dataset.customer!==b.dataset.customer);select.value='';const amount=modal.querySelector('[name="apply_amount"]');amount.value=b.dataset.remaining;amount.max=b.dataset.remaining});document.querySelector('[data-close-advance]')?.addEventListener('click',()=>modal.hidden=true);modal?.querySelector('[name="sale_id"]')?.addEventListener('change',e=>{const amount=modal.querySelector('[name="apply_amount"]'),balance=Number(e.target.selectedOptions[0]?.dataset.balance||0),available=Number(amount.max||0);amount.value=Math.min(balance,available).toFixed(2)});const layout=document.querySelector('.advance-layout'),register=layout?.querySelector('section'),createPanel=layout?.querySelector('aside');if(register&&createPanel){const overlay=document.createElement('div');overlay.className='advance-create-overlay';overlay.hidden=true;const close=document.createElement('button');close.type='button';close.className='icon-button advance-create-close';close.textContent='×';close.setAttribute('aria-label','Close advance form');createPanel.prepend(close);overlay.appendChild(createPanel);document.body.appendChild(overlay);const actions=document.createElement('div');actions.className='advance-register-actions';const add=document.createElement('button');add.type='button';add.className='btn primary';add.textContent='+ Receive New Advance';actions.appendChild(add);register.querySelector('.panel-head')?.appendChild(actions);const open=()=>{overlay.hidden=false;document.body.classList.add('modal-open');createPanel.querySelector('[name="customer_id"]')?.focus()},hide=()=>{overlay.hidden=true;document.body.classList.remove('modal-open')};add.addEventListener('click',open);close.addEventListener('click',hide);overlay.addEventListener('click',e=>{if(e.target===overlay)hide()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!overlay.hidden)hide()});if(new URLSearchParams(location.search).has('customer_id'))open()}</script>
<script>const advanceCustomerModal=document.querySelector('.advance-customer-modal'),advanceFormPanel=document.querySelector('.advance-create-overlay aside'),customerSelect=advanceFormPanel?.querySelector('[name="customer_id"]');if(advanceCustomerModal&&customerSelect){const createCustomerButton=document.createElement('button');createCustomerButton.type='button';createCustomerButton.className='btn secondary create-customer-from-advance';createCustomerButton.textContent='+ Customer not found? Create Customer';customerSelect.closest('label').after(createCustomerButton);createCustomerButton.addEventListener('click',()=>{advanceCustomerModal.hidden=false});document.querySelector('[data-close-advance-customer]')?.addEventListener('click',()=>advanceCustomerModal.hidden=true);advanceCustomerModal.addEventListener('click',e=>{if(e.target===advanceCustomerModal)advanceCustomerModal.hidden=true})}</script>
