<script>const advanceProductSelect=document.querySelector('#advance-product');if(advanceProductSelect){[...advanceProductSelect.options].forEach(option=>{const match=option.textContent.match(/Stock\s+(-?[\d.]+)/i);if(match&&Number(match[1])<=0)option.textContent=option.textContent.replace(/·\s*Stock\s+-?[\d.]+/i,'· OUT OF STOCK — advance order allowed')});const stockNote=document.createElement('p');stockNote.className='advance-stock-note';stockNote.textContent='Out-of-stock products can be reserved with an advance. Stock changes only when the final sale invoice is created.';advanceProductSelect.closest('label')?.after(stockNote)}</script>
